1	/**
2	 * Named scenario presets for the identity-wallet fake harness.
3	 *
4	 * Each preset builds a fresh {@link WalletState} that puts the app in a known
5	 * starting condition, so an agent (or a human) can reproduce any UI state — including
6	 * rare ones — on demand via `window.__harness.scenario(name)`. Pure functions over
7	 * `state.ts`, unit-testable in the Node environment.
8	 */
9	import {
10	  DEFAULT_PDS_URL,
11	  emptyWalletState,
12	  seedAgent,
13	  seedAlert,
14	  seedAppPassword,
15	  seedIdentity,
16	  upsertIdentity,
17	  type WalletState,
18	} from './state';
19	
20	/** The canonical wallet scenario names. */
21	export type ScenarioName =
22	  | 'fresh-install'
23	  | 'passwordless-signup'
24	  | 'foreign-pds'
25	  | 'unreachable-pds'
26	  | 'one-identity'
27	  | 'multi-identity'
28	  | 'alert-active'
29	  | 'migration-in-flight'
30	  | 'agent-connected'
31	  | 'app-password-minted'
32	  | 'device-key-unusable'
33	  | 'rekey-eligible'
34	  | 'rekey-mixed'
35	  | 'self-held-kit'
36	  | 'self-held-kit-escrow-host'
37	  | 'recover-escrow'
38	  | 'recover-sovereign'
39	  | 'recover-wrong-set'
40	  | 'recover-corrupt-share'
41	  | 'recover-mismatch'
42	  | 'recover-pending-delay'
43	  | 'recover-cancelled'
44	  | 'recover-epilogue-resume';
45	
46	/** The default scenario when `VITE_HARNESS` is set with no explicit choice. */
47	export const DEFAULT_SCENARIO: ScenarioName = 'one-identity';
48	
49	/** Every scenario builder, keyed by name. */
50	export const scenarios: Record<ScenarioName, () => WalletState> = {
51	  'fresh-install': () => emptyWalletState(),
52	
53	  /**
54	   * A first launch pointed at a Custos running with `accounts.password_optional` on, so it
55	   * advertises `optionalPassword` and the create flow never asks for a password: the handle
56	   * step submits directly, and `PasswordScreen` is not part of the flow at all.
57	   *
58	   * Deliberately a separate scenario rather than a capability added to `emptyWalletState`.
59	   * The flag is off by default on the server, so the default fixture keeps matching a stock
60	   * deployment — and every other scenario (and the docs screenshots built from them) keeps
61	   * exercising the with-password path, which is still what most hosts do.
62	   */
63	  'passwordless-signup': () => {
64	    const state = emptyWalletState();
65	    state.pdsCapabilities = {
66	      ...state.pdsCapabilities,
67	      capabilities: [...state.pdsCapabilities.capabilities, 'optionalPassword'],
68	    };
69	    return state;
70	  },
71	
72	  /**
73	   * A first launch pointed at a spec-compliant, non-Custos PDS: it advertises no Custos
74	   * capabilities, so the create flow's gate closes at the config step and steers to import.
75	   * This is the majority of the ecosystem (the reference PDS, bsky.social, rsky-pds), and
76	   * the only scenario that reaches `CreateUnavailableScreen`.
77	   */
78	  'foreign-pds': () => {
79	    const state = emptyWalletState();
80	    // Reached, and it genuinely advertises nothing — the answer that closes the gate.
81	    state.pdsCapabilities = { version: null, reached: true, capabilities: [] };
82	    state.availableUserDomains = ['.foreign.pds.local'];
83	    return state;
84	  },
85	
86	  /**
87	   * A host the capability probe could not reach. Indistinguishable from `foreign-pds`
88	   * through the capability list alone — which is the point: the create-flow gate must
89	   * show a retryable error here rather than telling the user their server cannot create
90	   * identities, a claim it has no evidence for.
91	   */
92	  'unreachable-pds': () => {
93	    const state = emptyWalletState();
94	    state.pdsCapabilities = { version: null, reached: false, capabilities: [] };
95	    return state;
96	  },
97	
98	  'one-identity': () => {
99	    const state = emptyWalletState();
100	    state.pdsUrl = DEFAULT_PDS_URL;
101	    upsertIdentity(state, seedIdentity({ handle: 'alice.harness.pds.local' }));
102	    return state;
103	  },
104	
105	  /**
106	   * A device restored from an encrypted backup: the device-key metadata restored, the
107	   * Secure Enclave key could not. The wallet must not claim custody of rotationKeys[0]
108	   * it cannot sign with — the card shows "Can't sign" and offers the recovery ceremony.
109	   */
110	  'device-key-unusable': () => {
111	    const state = emptyWalletState();
112	    state.pdsUrl = DEFAULT_PDS_URL;
113	    upsertIdentity(
114	      state,
115	      seedIdentity({ handle: 'alice.harness.pds.local', deviceKeyUnusable: true })
116	    );
117	    // The same loss on a did:web, where the ceremony does not apply: a did:web has no
118	    // rotation keys to rotate into, so the card must state the domain-side remedy rather
119	    // than offer a flow `start_share_recovery` refuses outright.
120	    upsertIdentity(
121	      state,
122	      seedIdentity({
123	        handle: 'web.example.com',
124	        did: 'did:web:web.example.com',
125	        deviceKeyUnusable: true,
126	      })
127	    );
128	    return state;
129	  },
130	
131	  'multi-identity': () => {
132	    const state = emptyWalletState();
133	    state.pdsUrl = DEFAULT_PDS_URL;
134	    upsertIdentity(state, seedIdentity({ handle: 'alice.harness.pds.local' }));
135	    upsertIdentity(
136	      state,
137	      seedIdentity({ handle: 'bob.harness.pds.local', deviceKeyIsRoot: false })
138	    );
139	    return state;
140	  },
141	
142	  'alert-active': () => {
143	    const state = emptyWalletState();
144	    state.pdsUrl = DEFAULT_PDS_URL;
145	    const identity = seedIdentity({ handle: 'alice.harness.pds.local' });
146	    // A recent unauthorized change so the recovery-window countdown is live.
147	    identity.alerts = [seedAlert(identity.did, isoHoursAgo(2))];
148	    upsertIdentity(state, identity);
149	    return state;
150	  },
151	
152	  'migration-in-flight': () => {
153	    const state = emptyWalletState();
154	    state.pdsUrl = DEFAULT_PDS_URL;
155	    const identity = seedIdentity({ handle: 'alice.harness.pds.local' });
156	    upsertIdentity(state, identity);
157	    // A prepared migration whose source is already authenticated and the destination
158	    // account created, so the migration screens land mid-flow.
159	    state.migration = {
160	      did: identity.did,
161	      destPdsUrl: 'https://destination.harness.pds.local',
162	      sourceAuthenticated: true,
163	      destinationCreated: true,
164	      repoTransferred: false,
165	      blobsTransferred: false,
166	      preferencesTransferred: false,
167	      verified: false,
168	      armed: false,
169	    };
170	    return state;
171	  },
172	
173	  'agent-connected': () => {
174	    const state = emptyWalletState();
175	    state.pdsUrl = DEFAULT_PDS_URL;
176	    const identity = seedIdentity({ handle: 'alice.harness.pds.local' });
177	    identity.agents = [seedAgent(identity.did, identity.did)];
178	    upsertIdentity(state, identity);
179	    return state;
180	  },
181	
182	  // Happy path A (escrow-assisted): Share 1 in iCloud, escrow releases the moment
183	  // the emailed code is entered (zero-delay server config).
184	  'recover-escrow': () => {
185	    const state = emptyWalletState();
186	    state.recovery.share1Present = true;
187	    state.recovery.escrow.delaySecs = 0;
188	    return state;
189	  },
190	
191	  // Happy path B (fully sovereign): Share 1 in iCloud + Share 3 entered manually.
192	  // Paste `state().recovery.fixtures.share3Words` (or `.share3`) into the entry box.
193	  'recover-sovereign': () => {
194	    const state = emptyWalletState();
195	    state.recovery.share1Present = true;
196	    return state;
197	  },
198	
199	  // Entering `fixtures.wrongSet` reports a cross-generation SHARE_SET_MISMATCH.
200	  'recover-wrong-set': () => {
201	    const state = emptyWalletState();
202	    state.recovery.share1Present = true;
203	    return state;
204	  },
205	
206	  // Entering `fixtures.corrupt` reports SHARE_CHECKSUM (damaged/mistyped share).
207	  'recover-corrupt-share': () => {
208	    const state = emptyWalletState();
209	    state.recovery.share1Present = true;
210	    return state;
211	  },
212	
213	  // Valid shares that don't belong to this identity: verification fails with
214	  // SHARES_DO_NOT_MATCH_IDENTITY before anything signs.
215	  'recover-mismatch': () => {
216	    const state = emptyWalletState();
217	    state.recovery.share1Present = true;
218	    state.recovery.verifyOutcome = 'mismatch';
219	    return state;
220	  },
221	
222	  // The escrow release opens a 24h pending window; the second poll releases, so
223	  // both the wait state and the arrival are reachable.
224	  'recover-pending-delay': () => {
225	    const state = emptyWalletState();
226	    state.recovery.share1Present = true;
227	    state.recovery.escrow.delaySecs = 86400;
228	    state.recovery.escrow.releaseAfterPolls = 2;
229	    return state;
230	  },
231	
232	  // The pending release was cancelled from a signed-in device: polls answer the
233	  // uniform 401 and the wait screen shows the cancelled state.
234	  'recover-cancelled': () => {
235	    const state = emptyWalletState();
236	    state.recovery.share1Present = true;
237	    state.recovery.escrow.delaySecs = 86400;
238	    state.recovery.escrow.cancelled = true;
239	    return state;
240	  },
241	
242	  // An app restart interrupted the rotation epilogue mid-way: launch resumes
243	  // straight to the epilogue screen, which re-runs only the incomplete steps.
244	  'recover-epilogue-resume': () => {
245	    const state = emptyWalletState();
246	    state.pdsUrl = DEFAULT_PDS_URL;
247	    const identity = seedIdentity({ handle: 'alice.harness.pds.local' });
248	    upsertIdentity(state, identity);
249	    state.recovery.did = identity.did;
250	    state.recovery.handle = identity.handle;
251	    state.recovery.epilogue = {
252	      opSubmitted: true,
253	      escrowDeposited: false,
254	      escrowSkipped: false,
255	      share1Written: false,
256	    };
257	    return state;
258	  },
259	
260	  'app-password-minted': () => {
261	    const state = emptyWalletState();
262	    state.pdsUrl = DEFAULT_PDS_URL;
263	    const identity = seedIdentity({ handle: 'alice.harness.pds.local' });
264	    // One plain credential and one privileged (chat-capable) one, so the list
265	    // screen's privilege badge and per-entry revoke are both reachable.
266	    identity.appPasswords = [
267	      seedAppPassword('Bluesky app'),
268	      seedAppPassword('Chat client', true),
269	    ];
270	    upsertIdentity(state, identity);
271	    return state;
272	  },
273	
274	  // A single old-model did:plc identity (2-key rotationKeys) — the "Add a recovery key" strip
275	  // shows and the full re-key upgrade runs (MM-411).
276	  'rekey-eligible': () => {
277	    const state = emptyWalletState();
278	    state.pdsUrl = DEFAULT_PDS_URL;
279	    upsertIdentity(
280	      state,
281	      seedIdentity({ handle: 'alice.harness.pds.local', recoveryKey: false })
282	    );
283	    return state;
284	  },
285	
286	  // Old-model + new-model + did:web side by side — only the old-model identity is offered the
287	  // upgrade, proving the prompt skips new-model and did:web identities.
288	  'rekey-mixed': () => {
289	    const state = emptyWalletState();
290	    state.pdsUrl = DEFAULT_PDS_URL;
291	    upsertIdentity(
292	      state,
293	      seedIdentity({ handle: 'oldmodel.harness.pds.local', recoveryKey: false })
294	    );
295	    upsertIdentity(
296	      state,
297	      seedIdentity({ handle: 'newmodel.harness.pds.local', recoveryKey: true })
298	    );
299	    upsertIdentity(
300	      state,
301	      seedIdentity({ handle: 'web.example.com', did: 'did:web:web.example.com' })
302	    );
303	    return state;
304	  },
305	
306	  /**
307	   * A claimed identity on a spec-compliant non-Custos host: device key at rotationKeys[0], a
308	   * longer tail than the Custos re-key's `[device, PDS]`, no recovery key, and a host that
309	   * answered describeServer advertising nothing. This is the escrow-less self-held kit's whole
310	   * population — the identity detail screen offers "Add a recovery key", and the backup step
311	   * hands the user Shares 2 AND 3 rather than escrowing one (MM-456).
312	   */
313	  'self-held-kit': () => {
314	    const state = emptyWalletState();
315	    state.pdsUrl = 'https://bsky.social';
316	    state.pdsCapabilities = { version: null, reached: true, capabilities: [] };
317	    const identity = seedIdentity({
318	      handle: 'alice.bsky.social',
319	      pdsUrl: 'https://bsky.social',
320	      recoveryKey: false,
321	    });
322	    // The tail a claim leaves behind: the old host's own keys, which the kit must shift down
323	    // intact rather than replace. Two of them, so the array is the length `guard_rekey_op`
324	    // rejects — the shape only this flow can serve.
325	    identity.rotationKeys = [
326	      identity.deviceKeyId,
327	      'did:key:zharnessForeignPdsKey',
328	      'did:key:zharnessForeignLegacyKey',
329	    ];
330	    upsertIdentity(state, identity);
331	    return state;
332	  },
333	
334	  /**
335	   * The same identity after the kit, now hosted somewhere that DOES advertise escrow — the
336	   * upsell seam's only true state. `self_held_kit_escrow_offer_cmd` answers true here and
337	   * false everywhere else, and "Add a recovery key" is withheld (there is nothing to add).
338	   */
339	  'self-held-kit-escrow-host': () => {
340	    const state = emptyWalletState();
341	    state.pdsUrl = DEFAULT_PDS_URL;
342	    state.pdsCapabilities = {
343	      version: '0.8.5',
344	      reached: true,
345	      capabilities: ['createCeremony', 'escrow', 'sovereignSessions'],
346	    };
347	    const identity = seedIdentity({ handle: 'alice.harness.pds.local', recoveryKey: true });
348	    identity.selfHeldKitInstalled = true;
349	    upsertIdentity(state, identity);
350	    return state;
351	  },
352	};
353	
354	/** Whether a string names a known scenario. */
355	export function isScenarioName(name: string): name is ScenarioName {
356	  return name in scenarios;
357	}
358	
359	/** Build a state for `name`, falling back to the default for an unknown name. */
360	export function buildScenario(name: string): WalletState {
361	  return isScenarioName(name) ? scenarios[name]() : scenarios[DEFAULT_SCENARIO]();
362	}
363	
364	/**
365	 * An ISO timestamp `hours` before now — measured against the *live* clock, deliberately.
366	 *
367	 * The recovery-window UI reads these fixtures against `Date.now()` (`$lib/deadline`'s
368	 * `getUrgency`/`formatCountdown`, via `$lib/identity-status`), so a fixed base instant is
369	 * not a fixed *age*: it ages out. Pinned to a literal date, `isoHoursAgo(2)` stops being a
370	 * two-hour-old alert the moment real time passes it, and once 72 hours have elapsed the
371	 * `alert-active` scenario renders "Recovery window closed" — the one preset that exists to
372	 * demonstrate a live alarm no longer demonstrating one.
373	 *
374	 * Determinism for the docs screenshots is owned by the capture driver, not by a constant
375	 * here: `tools/screenshots/capture.mjs` freezes the page clock to `FIXED_CLOCK` before the
376	 * harness installs, so `Date.now()` there is that instant and every seeded age resolves
377	 * identically on every run.
378	 */
379	function isoHoursAgo(hours: number): string {
380	  return new Date(Date.now() - hours * 3600_000).toISOString();
381	}
382

